import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { FaLinkedin, FaGithub, FaEnvelope } from "react-icons/fa";

/** Global background particle CSS (insert at top) */
const ParticleStyles = () => (
  <style>{`
    .particles {
      position: absolute;
      width: 100%;
      height: 100%;
      pointer-events: none;
      background-image:
        radial-gradient(circle at 10% 20%, rgba(66,153,225,0.15) 0%, transparent 40%),
        radial-gradient(circle at 80% 80%, rgba(29,78,216,0.15) 0%, transparent 50%);
      background-size: cover;
      animation: moveBG 12s infinite alternate ease‑in‑out;
    }
    @keyframes moveBG {
      from { background-position: 0% 0%; }
      to { background-position: 100% 100%; }
    }
  `}</style>
);

// Navbar
const Navbar = ({ activeSection, toggleDarkMode, darkMode }) => (
  <nav className="fixed w-full z-50 bg‑white dark:bg‑gray‑900 shadow">
    <div className="max‑w‑6xl mx‑auto px‑6 py‑4 flex justify‑between items‑center">
      <div className="text‑2xl font‑bold text‑brandBlue">Muhammed Fazal</div>
      <div className="hidden md:flex space‑x‑6 items‑center">
        {["about","skills","experience","projects","contact"].map(sec => (
          <a
            key={sec}
            href={`#${sec}`}
            className={`hover:text‑brandBlue ${
              activeSection === sec ? "text‑brandBlue font‑semibold" : ""
            }`}
          >
            {sec.charAt(0).toUpperCase()+sec.slice(1)}
          </a>
        ))}
        <button
          onClick={toggleDarkMode}
          className="ml‑4 px‑3 py‑1 bg‑brandBlue text‑white rounded hover:bg‑brandBlueLight transition"
        >
          {darkMode ? "Light" : "Dark"}
        </button>
      </div>
    </div>
  </nav>
);

// Social floating icons
const SocialIcons = () => (
  <div className="fixed left‑6 top‑1/3 flex flex‑col space‑y‑4 z‑50">
    <a href="https://linkedin.com/in/muhammedfazal" target="_blank" className="text‑brandBlue text‑2xl hover:scale‑110 transform transition">
      <FaLinkedin />
    </a>
    <a href="https://github.com/muhammedfazal" target="_blank" className="text‑brandBlue text‑2xl hover:scale‑110 transform transition">
      <FaGithub />
    </a>
    <a href="mailto:muhammedfazalkv@gmail.com" className="text‑brandBlue text‑2xl hover:scale‑110 transform transition">
      <FaEnvelope />
    </a>
  </div>
);

// Hero
const Hero = () => (
  <section id="home" className="relative h‑screen flex flex‑col justify‑center items‑center text‑white text‑center overflow‑hidden">
    <div className="particles"></div>
    <motion.h1 className="relative text‑5xl md:text‑6xl font‑bold mb‑4 z‑10 text‑brandBlue"
      initial={{ opacity:0, y:-50 }} animate={{ opacity:1, y:0 }} transition={{ duration:1 }}>
      Muhammed Fazal
    </motion.h1>
    <motion.p className="relative text‑xl md:text‑2xl mb‑6 max‑w‑2xl z‑10 text‑gray‑700 dark:text‑gray‑300"
      initial={{ opacity:0, y:50 }} animate={{ opacity:1, y:0 }} transition={{ delay:0.5,duration:1 }}>
      Backend‑focused Full Stack Developer with 6+ years building scalable backend systems.
    </motion.p>
  </section>
);

// — (other sections: About, Skills, Experience, Projects, Contact) —
// * Use className text‑brandBlue for headings, bg‑brandBlue/light for accent elements.
// * Include <div className="particles"></div> at top of each section if you want repeating moving background.

const About = () => (
  <motion.section id="about" className="py‑20 relative bg‑gray‑50 dark:bg‑gray‑800"
    initial={{ opacity:0 }} whileInView={{ opacity:1 }} viewport={{ once:true }} transition={{ duration:1 }}>
    <div className="particles"></div>
    <div className="max‑w‑4xl mx‑auto px‑6">
      <h2 className="text‑4xl font‑bold text‑brandBlue mb‑6 text‑center">About Me</h2>
      <p>/* your full profile text */</p>
    </div>
  </motion.section>
);

// (Repeat similar structure for Skills, Experience, Projects, Contact ...)
